pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount, address adr) public {
        bound(amount, 1, 1e36);
        vm.assume(adr != address(0) && adr != address(c));

        vm.deal(address(this), amount);
        bytes memory data = "";
        c.Command{value: amount}(adr, data);

        assertTrue(adr.balance >= amount);
    }
}
